// Local verification harness only: preserve test-owned HOME fixtures, and give
// every other test file its own temporary Coven home instead of sharing state.
import childProcess from 'node:child_process';
import { syncBuiltinESMExports } from 'node:module';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
if (process.argv[1]?.endsWith('/scripts/run-tests.mjs')) {
  const original = childProcess.spawnSync;
  childProcess.spawnSync = function(command, args, options) {
    const file = args?.find((value) => /\.test\.(?:ts|tsx|mjs)$/.test(value));
    if (!file) return original(command, args, options);
    const root = mkdtempSync(path.join(tmpdir(), 'cave-5765-suite-file-'));
    const env = { ...options.env };
    delete env.COVEN_CAVE_HOME;
    delete env.COVEN_SOCKET;
    const source = readFileSync(path.resolve(options.cwd, file), 'utf8');
    if (/process\.env\.HOME\s*=/.test(source)) delete env.COVEN_HOME;
    else env.COVEN_HOME = path.join(root, 'coven');
    try { return original(command, args, { ...options, env }); }
    finally { rmSync(root, { recursive: true, force: true }); }
  };
  syncBuiltinESMExports();
}
